package com.thangit.boardinghouse.service;

import com.thangit.boardinghouse.domain.auth.RoleCode;
import com.thangit.boardinghouse.security.AuthenticatedUser;
import com.thangit.boardinghouse.repository.AdminInvoiceRepository;
import com.thangit.boardinghouse.dto.request.invoice.AdminInvoiceRequests.*;
import com.thangit.boardinghouse.dto.response.invoice.AdminInvoiceResponses.*;
import java.math.BigDecimal;
import java.time.*;
import java.util.*;
import org.springframework.jdbc.core.simple.JdbcClient;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.TransactionDefinition;
import org.springframework.transaction.support.TransactionTemplate;

/** One transaction per contract: a missing meter never rolls back another room's invoice. */
@Service
public class BillingBatchService {
    private final JdbcClient db;private final AdminInvoiceService invoices;private final TransactionTemplate tx;private final AdminInvoiceRepository repo;
    public BillingBatchService(JdbcClient db,AdminInvoiceService invoices,PlatformTransactionManager manager){this.db=db;this.invoices=invoices;this.repo=new AdminInvoiceRepository(db);this.tx=new TransactionTemplate(manager);tx.setPropagationBehavior(TransactionDefinition.PROPAGATION_REQUIRES_NEW);}
    private List<Map<String,Object>> candidates(AuthenticatedUser p,BulkInvoice r){if(p==null||!Set.of(RoleCode.OWNER,RoleCode.MANAGER,RoleCode.ACCOUNTANT).contains(p.activeRole())||!repo.canAccess(p.id(),p.activeRole(),r.propertyId()))throw MonthlyBillingService.fail("INVOICE_PROPERTY_DENIED","Không có quyền khu trọ.");LocalDate period=LocalDate.parse(r.billingPeriod()+"-01");return db.sql("SELECT c.*,c.agreed_monthly_rent monthly_rent,r.code room_code,r.property_id FROM contracts c JOIN rooms r ON r.id=c.room_id WHERE r.property_id=:id AND c.start_date<:end AND c.end_date>:start AND c.status IN ('ACTIVE','EXPIRING','EXPIRED','SETTLING','TERMINATION_REQUESTED') ORDER BY c.id").param("id",r.propertyId()).param("start",period).param("end",period.plusMonths(1)).query().listOfRows().stream().filter(c->r.roomIds()==null||r.roomIds().isEmpty()||r.roomIds().contains(MonthlyBillingService.id(c,"room_id"))).toList();}
    private SaveInvoice request(BulkInvoice r,Map<String,Object> c){LocalDate period=LocalDate.parse(r.billingPeriod()+"-01");return new SaveInvoice(MonthlyBillingService.id(c,"room_id"),MonthlyBillingService.id(c,"id"),r.billingPeriod(),period,period.plusMonths(1).minusDays(1),r.issueDate(),r.dueDate(),List.of(),BigDecimal.ZERO,false,null,r.action()==null?"SAVE_DRAFT":r.action(),null);}
    public List<BulkPreviewRow> preview(AuthenticatedUser p,BulkInvoice r){var out=new ArrayList<BulkPreviewRow>();for(var c:candidates(p,r))try{out.add(tx.execute(s->{long id=MonthlyBillingService.id(c,"id");if(repo.duplicate(id,LocalDate.parse(r.billingPeriod()+"-01"),null))return row(c,"SKIPPED","Đã có hóa đơn",BigDecimal.ZERO);var locked=repo.contractForRoom(MonthlyBillingService.id(c,"room_id"),id).orElseThrow();var plan=repo.calculate(request(r,c),locked);return row(c,"READY",null,plan.items().stream().map(MonthlyBillingService.Charge::amount).reduce(BigDecimal.ZERO,BigDecimal::add));}));}catch(RuntimeException e){out.add(row(c,"BLOCKED",e.getMessage(),BigDecimal.ZERO));}return out;}
    private BulkPreviewRow row(Map<String,Object> c,String status,String message,BigDecimal amount){return new BulkPreviewRow(MonthlyBillingService.id(c,"room_id"),Objects.toString(c.get("room_code"),""),Objects.toString(c.get("code"),""),amount,status,message);}
    public BulkResult generate(AuthenticatedUser p,BulkInvoice r){var created=new ArrayList<CreateResult>();var skipped=new ArrayList<BulkPreviewRow>();for(var c:candidates(p,r))try{var result=tx.execute(s->invoices.create(p,request(r,c)));created.add(result);}catch(RuntimeException e){skipped.add(row(c,"FAILED",e.getMessage(),BigDecimal.ZERO));}return new BulkResult(created,skipped);}
    public void scheduled(LocalDate today){var settings=db.sql("SELECT b.*,p.id property_id,p.owner_id FROM billing_settings b JOIN properties p ON p.owner_id=b.owner_id WHERE b.auto_generate_invoices=TRUE AND p.status='ACTIVE'").query().listOfRows();for(var config:settings){if(today.getDayOfMonth()<((Number)config.get("invoice_generation_day")).intValue())continue;LocalDate period=today.withDayOfMonth(1).plusMonths(((Number)config.get("billing_period_offset")).intValue());if(period.equals(today.withDayOfMonth(1))&&today.getDayOfMonth()<((Number)config.get("meter_cutoff_day")).intValue())continue;var owner=new AuthenticatedUser(MonthlyBillingService.id(config,"owner_id"),"scheduler",RoleCode.OWNER);LocalDate due=today.withDayOfMonth(((Number)config.get("default_due_day")).intValue());if(due.isBefore(today))due=due.plusMonths(1);var bulk=new BulkInvoice(MonthlyBillingService.id(config,"property_id"),period.toString().substring(0,7),today,due,null,"SAVE_DRAFT");for(var c:candidates(owner,bulk)){long contract=MonthlyBillingService.id(c,"id");try{tx.executeWithoutResult(s->{new RoomLifecycleGuard(db).lockContract(contract);db.sql("INSERT IGNORE INTO billing_run_results(contract_id,billing_period,status) VALUES(:id,:period,'PENDING')").param("id",contract).param("period",period).update();var run=db.sql("SELECT * FROM billing_run_results WHERE contract_id=:id AND billing_period=:period FOR UPDATE").param("id",contract).param("period",period).query().singleRow();
                    Long invoice=run.get("invoice_id")==null?null:((Number)run.get("invoice_id")).longValue();if(invoice==null){if(repo.duplicate(contract,period,null)){result(contract,period,"SKIPPED",null,"Hóa đơn thủ công đã tồn tại");return;}invoice=invoices.create(owner,request(bulk,c)).id();db.sql("UPDATE invoices SET is_automated=TRUE WHERE id=:id").param("id",invoice).update();}
                    var i=repo.invoice(invoice,true).orElseThrow();if(!Boolean.TRUE.equals(i.get("is_automated"))){result(contract,period,"SKIPPED",invoice,"B?n nh?p ?? ???c ti?p qu?n th? c?ng");return;}if(Boolean.TRUE.equals(config.get("auto_issue_invoices"))&&today.getDayOfMonth()>=((Number)config.get("auto_issue_day")).intValue()&&"DRAFT".equals(i.get("status"))){invoices.issue(owner,invoice,MonthlyBillingService.id(i,"version"));i=repo.invoice(invoice,true).orElseThrow();}result(contract,period,i.get("status").toString(),invoice,"Đã kiểm tra dữ liệu");});}catch(RuntimeException e){tx.executeWithoutResult(s->{new RoomLifecycleGuard(db).lockContract(contract);db.sql("INSERT IGNORE INTO billing_run_results(contract_id,billing_period,status) VALUES(:id,:period,'FAILED')").param("id",contract).param("period",period).update();result(contract,period,"FAILED",null,Objects.toString(e.getMessage(),"Lỗi tính tiền"));});}}}}
    private void result(long contract,LocalDate period,String status,Long invoice,String message){db.sql("UPDATE billing_run_results SET status=:status,invoice_id=COALESCE(:invoice,invoice_id),attempts=attempts+1,message=:message,attempted_at=NOW(6) WHERE contract_id=:id AND billing_period=:period").param("status",status).param("invoice",invoice).param("message",message.substring(0,Math.min(1000,message.length()))).param("id",contract).param("period",period).update();}
}
